head.b:skin:
/* SUSHI ELITE v84.0 STABLE */
:root {
    --primary: #ce1212; --primary-dark: #a00d0d;
    --secondary: #37373f; --accent: #ffc107;
    --bg-body: #f8f9fa; --bg-card: #ffffff;
    --text-main: #1d1d1f; --text-muted: #86868b;
    --font-main: "Inter", sans-serif; --font-header: "Amatic SC", sans-serif;
    --radius-xl: 20px;
    --z-marquee: 1040; --z-navbar: 1030; --z-bread: 1025; --z-floating: 1035; --z-toast: 1060;
}

[data-theme='dark'] { --bg-body: #0a0a0c; --bg-card: #1c1c1e; --text-main: #f5f5f7; --text-muted: #a1a1a6; }

body { font-family: var(--font-main); background: var(--bg-body); color: var(--text-main); padding-top: 145px; padding-bottom: 90px; overflow-x: hidden; -webkit-tap-highlight-color: transparent; font-size: 0.92rem; }

html[dir="rtl"] body { text-align: right; }
html[dir="rtl"] .offcanvas-start { right: 0; left: auto; transform: translateX(100%); }
html[dir="rtl"] .me-2 { margin-left: 0.5rem !important; margin-right: 0 !important; }
html[dir="rtl"] .ms-2 { margin-right: 0.5rem !important; margin-left: 0 !important; }
html[dir="rtl"] .ms-3 { margin-right: 1rem !important; margin-left: 0 !important; }
html[dir="rtl"] .ms-auto { margin-right: auto !important; margin-left: 0 !important; }
html[dir="rtl"] .badge-float { right: auto; left: 10px; } 
html[dir="rtl"] .wish-btn-card { left: 10px; right: auto; }
html[dir="rtl"] .rounded-start-pill { border-top-right-radius: 50rem!important; border-bottom-right-radius: 50rem!important; border-top-left-radius: 0!important; border-bottom-left-radius: 0!important; }
html[dir="rtl"] .rounded-end-pill { border-top-left-radius: 50rem!important; border-bottom-left-radius: 50rem!important; border-top-right-radius: 0!important; border-bottom-right-radius: 0!important; }
html[dir="rtl"] .floating-cart .price-tag { margin-left: 0; margin-right: 10px; }

.marquee-bar { position: fixed; top: 0; left: 0; width: 100%; height: 30px; background: #000; color: #fff; z-index: var(--z-marquee); overflow: hidden; display: flex; align-items: center; font-size: 0.75rem; font-weight: bold; text-transform: uppercase; letter-spacing: 1px; }
.marquee-content { display: inline-block; white-space: nowrap; animation: marquee 20s linear infinite; padding-left: 100%; }
@keyframes marquee { 0% { transform: translate(0, 0); } 100% { transform: translate(-100%, 0); } }

.header { background: var(--bg-card); height: 80px; z-index: var(--z-navbar); border-bottom: 1px solid rgba(0,0,0,0.05); top: 30px; transition: 0.3s; }

.breadcrumb-bar { position: fixed; top: 110px; left: 0; width: 100%; height: 35px; background: var(--bg-body); z-index: var(--z-bread); display: flex; align-items: center; padding: 0 15px; border-bottom: 1px solid rgba(0,0,0,0.05); font-size: 0.8rem; overflow-x: auto; white-space: nowrap; }
.breadcrumb-item a { text-decoration: none; color: var(--text-muted); font-weight: 500; }
.breadcrumb-item.active { color: var(--primary); font-weight: 700; }
.breadcrumb-sep { margin: 0 8px; color: #ccc; }

.card, .product-card { background: var(--bg-card) !important; border: 1px solid rgba(0,0,0,0.05); }

.product-card { border-radius: var(--radius-xl); overflow: hidden; height: 100%; transition: 0.3s cubic-bezier(0.165, 0.84, 0.44, 1); position: relative; }
.product-card:hover { transform: translateY(-5px); box-shadow: 0 10px 30px rgba(0,0,0,0.1); }

.product-img-wrapper { position: relative; width: 100%; aspect-ratio: 4 / 3; overflow: hidden; background: #f0f0f0; cursor: pointer; }
.product-img { width: 100%; height: 100%; object-fit: cover; transition: transform 0.5s ease; }
.product-card:hover .product-img { transform: scale(1.05); }

.wish-btn-card { position: absolute; bottom: 10px; right: 10px; z-index: 10; width: 35px; height: 35px; background: rgba(255,255,255,0.9); backdrop-filter: blur(4px); border-radius: 50%; border: none; display: flex; align-items: center; justify-content: center; color: #ccc; transition: 0.2s; box-shadow: 0 2px 8px rgba(0,0,0,0.1); cursor: pointer; }
.wish-btn-card.active { color: var(--primary); transform: scale(1.1); }

.badge-float { position: absolute; z-index: 10; padding: 4px 10px; border-radius: 4px; font-weight: 800; font-size: 0.65rem; color: #fff; box-shadow: 0 4px 10px rgba(0,0,0,0.2); }
.badge-hot { top: 10px; left: 10px; background: linear-gradient(45deg, #ff0000, #ff8800); }
.badge-stock { top: 10px; left: 10px; background: rgba(0,0,0,0.7); backdrop-filter: none; } 
.badge-low { background: #e67e22; top: 10px; left: 10px; animation: pulse 2s infinite; }
.badge-out { background: #c0392b; top: 10px; left: 10px; }
.badge-sale { top: 38px; left: 10px; background: #000; } 

@keyframes pulse { 0% { opacity: 1; } 50% { opacity: 0.6; } 100% { opacity: 1; } }

.desktop-actions { position: absolute; bottom: 10px; left: 50%; transform: translateX(-50%) translateY(20px); opacity: 0; transition: 0.3s; z-index: 20; width: 90%; text-align: center; }
.product-card:hover .desktop-actions { opacity: 1; transform: translateX(-50%) translateY(0); }
@media (max-width: 991px) { .desktop-actions { display: none; } }

.product-title { font-weight: 700; line-height: 1.3; font-size: 0.95rem; margin-bottom: 8px; display: block; white-space: normal; }

.floating-cart { position: fixed; bottom: 85px; left: 15px; right: 15px; background: rgba(29, 29, 31, 0.85); backdrop-filter: blur(10px); color: #fff; padding: 12px 20px; border-radius: 50px; z-index: var(--z-floating); display: flex; justify-content: space-between; align-items: center; box-shadow: 0 10px 30px rgba(0,0,0,0.25); transform: translateY(150%); transition: 0.4s cubic-bezier(0.175, 0.885, 0.32, 1.275); }
.floating-cart.active { transform: translateY(0); }
.floating-cart .price-tag { background: rgba(255,255,255,0.2); padding: 4px 12px; border-radius: 20px; font-weight: 700; margin-left: 10px; }

.qv-wrapper { padding: 20px; }

.filter-scroll { display: flex; gap: 8px; overflow-x: auto; padding-bottom: 5px; scrollbar-width: none; }
.filter-scroll::-webkit-scrollbar { display: none; }
.filter-chip { white-space: nowrap; padding: 8px 18px; border-radius: 50px; background: var(--bg-card); border: 1px solid rgba(0,0,0,0.1); color: var(--text-muted); font-weight: 600; cursor: pointer; transition: 0.3s; font-size: 0.85rem; }
.filter-chip:hover, .filter-chip.active { background: var(--primary); color: #fff; border-color: var(--primary); }

.fly-img { position: fixed; z-index: 9999; transition: all 0.8s cubic-bezier(0.19, 1, 0.22, 1); border-radius: 50%; object-fit: cover; pointer-events: none; box-shadow: 0 10px 30px rgba(0,0,0,0.3); }

.toast-container { position: fixed; bottom: 100px; left: 50%; transform: translateX(-50%); z-index: var(--z-toast); width: 90%; max-width: 350px; pointer-events: none; }
.toast { pointer-events: auto; background: var(--bg-card); color: var(--text-main); border: 1px solid rgba(0,0,0,0.1); box-shadow: var(--shadow-lg); border-radius: 12px; margin-bottom: 10px; }

#scroll-sentinel { height: 50px; width: 100%; display: flex; justify-content: center; align-items: center; margin-top: 20px; }
.module-section { display: none !important; opacity: 0; animation: fadeIn 0.4s forwards; }
.module-section.active { display: block !important; opacity: 1; }
@keyframes fadeIn { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: translateY(0); } }

.swatch-item { padding: 8px 16px; border-radius: 8px; cursor: pointer; border: 2px solid transparent; background: #eee; font-size: 0.9rem; font-weight: 600; color: #555; transition: 0.2s; margin-right:8px; margin-bottom:8px; display:inline-block; }
.swatch-item.active { border-color: var(--primary); background: var(--primary); color: #fff; }

.delivery-progress { height: 8px; background: #eee; border-radius: 10px; overflow: hidden; margin-top: 5px; }
.delivery-bar { height: 100%; background: var(--primary); width: 0%; transition: width 0.5s; }

.stock-dot { width: 8px; height: 8px; border-radius: 50%; display: inline-block; margin-right: 5px; }
.bg-stock-ok { background-color: #198754; }
.bg-stock-low { background-color: #ffc107; }
.bg-stock-out { background-color: #dc3545; }
.variant-select { font-size: 0.85rem; padding: 2px 8px; border-radius: 4px; border: 1px solid #ddd; background: var(--bg-body); color: var(--text-main); cursor: pointer; }

.header-action-btn { background: transparent; border: 1px solid rgba(0,0,0,0.1); border-radius: 50%; width: 35px; height: 35px; display: flex; align-items: center; justify-content: center; font-size: 1rem; cursor: pointer; transition: 0.2s; }
.header-action-btn:hover { background: #eee; }

@media (max-width: 768px) {
    .modal.fade .modal-dialog { transform: translate(0, 100%); margin: 0; position: fixed; bottom: 0; width: 100%; max-width: 100%; }
    .modal.show .modal-dialog { transform: none; }
    .modal-content { border-radius: 24px 24px 0 0; border: none; min-height: auto; padding-bottom: 20px; }
    .modal-body { overflow-y: auto; max-height: 80vh; }
}

body.script:
//

// 🔥 PASTE YOUR GOOGLE APPS SCRIPT WEB APP URL HERE 🔥
const API_URL = "https://script.google.com/macros/s/AKfycbxnDZiQY_tpQexinqIgq2H1xXEDvwrDpmnItcLh5uFGB1VqB12uh6M4-P6jGhSQmXwe/exec"; 

const App = {
    Config: {
        baseCurrency: 'MAD', freeShipThreshold: 150, shipCost: 15, waNumber: '212600000000',
        mockMenu: []
    },

    Strings: {
        'EN': { home:'🏠 Home', catalog:'Catalog', cart:'Cart', wishlist:'Wishlist', profile:'Profile', heroTitle:'Taste the Ocean', heroSub:'Premium Japanese Cuisine Delivered.', orderNow:'ORDER NOW', viewCart:'View Cart', yourOrder:'Your Order', share:'Share', empty:'Empty', cartEmptyTitle:'Your Cart is Empty', cartEmptySub:"Looks like you haven't added anything yet.", goToMenu:'Go to Menu', delMethod:'DELIVERY METHOD', delivery:'🛵 Delivery', pickup:'🛍️ Pickup', prefs:'Preferences', schedule:'SCHEDULE', notes:'NOTES / ALLERGIES', summary:'Summary', apply:'APPLY', subtotal:'Subtotal', discount:'Discount', tip:'Tip the Team', total:'Total', yourName:'Your Name', phoneNum:'Phone Number', delAddr:'Delivery Address', cash:'💵 Cash on Delivery', card:'💳 Card Terminal (TPE)', checkout:'CHECKOUT', favorites:'Favorites', history:'Order History', date:'Date', wishlistEmptyTitle:'Your Wishlist is Empty', wishlistEmptySub:'Save your favorite items here.', addMore:'Add more for FREE Delivery!', confirm:'Confirm', areYouSure:'Are you sure?', cancel:'Cancel', yes:'Yes, Proceed', addedToCart:'Added to Cart', outOfStock:'Out of Stock', lowStock:'Low Stock', soldOut:'Sold Out', inStock:'In Stock', qvSize:'SIZE / OPTION', qvQty:'Quantity', qvAdd:'ADD TO CART', qvBuy:'⚡ BUY NOW', qvShare:'SHARE', viewFull:'View Full Details', msgAlreadyEmpty:'List is already empty!', msgStockLimit:'Stock limit reached', msgMinQty:'Minimum 1', free:'FREE', left:'Left' },
        'FR': { home:'🏠 Accueil', catalog:'Menu', cart:'Panier', wishlist:'Favoris', profile:'Profil', heroTitle:'Goûtez l\'Océan', heroSub:'Cuisine Japonaise Premium Livrée.', orderNow:'COMMANDER', viewCart:'Voir Panier', yourOrder:'Votre Commande', share:'Partager', empty:'Vider', cartEmptyTitle:'Votre Panier est Vide', cartEmptySub:"Vous n'avez rien ajouté.", goToMenu:'Voir le Menu', delMethod:'MODE DE LIVRAISON', delivery:'🛵 Livraison', pickup:'🛍️ À Emporter', prefs:'Préférences', schedule:'HORAIRE', notes:'NOTES / ALLERGIES', summary:'Résumé', apply:'APPLIQUER', subtotal:'Sous-total', discount:'Remise', tip:'Pourboire', total:'Total', yourName:'Votre Nom', phoneNum:'Téléphone', delAddr:'Adresse de Livraison', cash:'💵 Espèces à la livraison', card:'💳 TPE (Carte Bancaire)', checkout:'COMMANDER', favorites:'Favoris', history:'Historique', date:'Date', wishlistEmptyTitle:'Votre Liste est Vide', wishlistEmptySub:'Sauvegardez vos favoris ici.', addMore:'Ajoutez pour Livraison GRATUITE!', confirm:'Confirmer', areYouSure:'Êtes-vous sûr?', cancel:'Annuler', yes:'Oui, Continuer', addedToCart:'Ajouté au Panier', outOfStock:'Rupture de Stock', lowStock:'Stock Faible', soldOut:'Épuisé', inStock:'En Stock', qvSize:'TAILLE / OPTION', qvQty:'Quantité', qvAdd:'AJOUTER', qvBuy:'⚡ ACHETER', qvShare:'PARTAGER', viewFull:'Voir Détails', msgAlreadyEmpty:'Déjà vide!', msgStockLimit:'Limite atteinte', msgMinQty:'Min 1', free:'GRATUIT', left:'Restant' },
        'AR': { home:'🏠 الرئيسية', catalog:'القائمة', cart:'السلة', wishlist:'المفضلة', profile:'حسابي', heroTitle:'تذوق المحيط', heroSub:'مأكولات يابانية فاخرة.', orderNow:'اطلب الآن', viewCart:'عرض السلة', yourOrder:'طلبيتك', share:'مشاركة', empty:'إفراغ', cartEmptyTitle:'سلتك فارغة', cartEmptySub:"لم تضف أي شيء بعد.", goToMenu:'الذهاب للقائمة', delMethod:'طريقة الاستلام', delivery:'🛵 توصيل', pickup:'🛍️ استلام من المحل', prefs:'تفضيلات', schedule:'التوقيت', notes:'ملاحظات', summary:'الملخص', apply:'تطبيق', subtotal:'المجموع الفرعي', discount:'خصم', tip:'إكرامية', total:'الإجمالي', yourName:'الاسم الكامل', phoneNum:'رقم الهاتف', delAddr:'عنوان التوصيل', cash:'💵 دفع عند الاستلام', card:'💳 بطاقة بنكية', checkout:'إتمام الطلب', favorites:'المفضلة', history:'سجل الطلبات', date:'التاريخ', wishlistEmptyTitle:'قائمة المفضلة فارغة', wishlistEmptySub:'احفظ أطباقك المفضلة هنا.', addMore:'أضف المزيد لتوصيل مجاني!', confirm:'تأكيد', areYouSure:'هل أنت متأكد؟', cancel:'إلغاء', yes:'نعم، تابع', addedToCart:'تمت الإضافة', outOfStock:'نفد المخزون', lowStock:'مخزون قليل', soldOut:'نفد', inStock:'متوفر', qvSize:'الحجم / الخيار', qvQty:'الكمية', qvAdd:'أضف للسلة', qvBuy:'⚡ شراء الآن', qvShare:'مشاركة', viewFull:'تفاصيل كاملة', msgAlreadyEmpty:'القائمة فارغة بالفعل!', msgStockLimit:'وصلت للحد الأقصى', msgMinQty:'أقل كمية 1', free:'مجاني', left:'متبقي' }
    },

    Symbols: { 'MAD': ' DH', 'EUR': ' €', 'USD': '$ ' },

    State: { catalog:[], visibleCount:0, batchSize:20, cart:[], wishlist:[], history:[], user:null, activeCat:'All', qvItem:null, qvMult:1.0, qvQty:1, orderType:'delivery', tip:0, currency:'MAD', lang:'EN', version:'84.0', lastActive: 0, lastCurrencyChange: 0, currentTotal: 0 },

    t: (key) => App.Strings[App.State.lang][key] || key,

    Auth: {
        openModal: () => new bootstrap.Modal(document.getElementById('authModal')).show(),
        login: () => {
            const p = document.getElementById('login-phone').value;
            const pass = document.getElementById('login-pass').value;
            if(!p || !pass) return App.UI.toast('Enter Phone & Password', 'danger');

            App.UI.toast('Logging in...', 'info');
            fetch(API_URL, { method: 'POST', body: JSON.stringify({ action: 'login', data: { phone: p, password: pass } }) })
            .then(r => r.json()).then(res => {
                if(res.status === 'success') {
                    App.State.user = { id: res.userId, name: res.name, phone: p };
                    localStorage.setItem('se_user', JSON.stringify(App.State.user));
                    bootstrap.Modal.getInstance(document.getElementById('authModal')).hide();
                    App.Auth.check();
                    App.UI.toast('Welcome back, ' + res.name);
                    App.API.syncDown(res.userId);
                } else App.UI.toast(res.message, 'danger');
            }).catch(() => App.UI.toast('Connection Error', 'danger'));
        },
        register: () => {
            const n = document.getElementById('reg-name').value;
            const p = document.getElementById('reg-phone').value;
            const pass = document.getElementById('reg-pass').value;
            if(!n || !p || !pass) return App.UI.toast('Fill all fields', 'danger');

            App.UI.toast('Creating Account...', 'info');
            fetch(API_URL, { method: 'POST', body: JSON.stringify({ action: 'register', data: { name: n, phone: p, password: pass } }) })
            .then(r => r.json()).then(res => {
                if(res.status === 'success') {
                    App.State.user = { id: res.userId, name: n, phone: p };
                    localStorage.setItem('se_user', JSON.stringify(App.State.user));
                    bootstrap.Modal.getInstance(document.getElementById('authModal')).hide();
                    App.Auth.check();
                    App.UI.toast('Account Created!');
                } else App.UI.toast(res.message, 'danger');
            });
        },
        logout: () => {
            localStorage.removeItem('se_user');
            App.State.user = null;
            App.Auth.check();
            App.UI.toast('Logged Out');
            App.Router();
        },
        check: () => {
            const u = App.State.user;
            const btn = document.getElementById('auth-btn');
            const pIn = document.getElementById('profile-logged-in');
            const pOut = document.getElementById('profile-logged-out');
            const historySec = document.getElementById('order-history-section');

            if(u) {
                btn.innerHTML = '<i class="bi bi-person-check-fill text-success"></i>';
                if(pIn) pIn.classList.remove('d-none'); 
                if(pOut) pOut.classList.add('d-none');
                if(historySec) historySec.classList.remove('d-none');
                if(document.getElementById('logout-btn-top')) document.getElementById('logout-btn-top').classList.remove('d-none');
                if(document.getElementById('user-name-display')) document.getElementById('user-name-display').innerText = u.name;
                if(document.getElementById('user-phone-display')) document.getElementById('user-phone-display').innerText = u.phone;
            } else {
                btn.innerHTML = '<i class="bi bi-person"></i>';
                if(pIn) pIn.classList.add('d-none'); 
                if(pOut) pOut.classList.remove('d-none');
                if(historySec) historySec.classList.add('d-none');
                if(document.getElementById('logout-btn-top')) document.getElementById('logout-btn-top').classList.add('d-none');
            }
        }
    },

    API: {
        init: () => {
            if(API_URL.includes('PASTE')) { App.Catalog.init(App.Config.mockMenu); return; } 
            fetch(API_URL + '?action=getCatalog').then(r => r.json()).then(res => {
                if(res.status === 'success') {
                    App.Catalog.init(res.data.map(i => ({
                        id: i.id, title: i.title, cat: i.category,
                        price_MAD: parseFloat(i.price_MAD), 
                        price_EUR: parseFloat(i.price_EUR), 
                        price_USD: parseFloat(i.price_USD),
                        oldPrice_MAD: parseFloat(i.oldPrice_MAD), 
                        oldPrice_EUR: parseFloat(i.oldPrice_EUR), 
                        oldPrice_USD: parseFloat(i.oldPrice_USD),
                        stock: i.stock, img: i.image, hot: (i.tags||'').includes('hot')
                    })));
                    if(App.State.user) App.API.syncDown(App.State.user.id);
                } else App.Catalog.init(App.Config.mockMenu);
            }).catch(() => App.Catalog.init(App.Config.mockMenu));
        },
        syncUp: () => {
            if(!App.State.user) return;
            if(App.syncTimer) clearTimeout(App.syncTimer);
            App.syncTimer = setTimeout(() => {
                const payload = { 
                    userId: App.State.user.id, 
                    cartJson: JSON.stringify(App.State.cart),
                    currency: App.State.currency
                };
                fetch(API_URL, { method: 'POST', body: JSON.stringify({ action: 'syncCart', data: payload }) });

                const wishPayload = { userId: App.State.user.id, items: App.State.wishlist.map(i=>i.id).join(',') };
                fetch(API_URL, { method: 'POST', body: JSON.stringify({ action: 'syncWishlist', data: wishPayload }) });
            }, 2000);
        },
        syncDown: (userId) => {
            fetch(API_URL + '?action=getUserData&userId=' + userId).then(r=>r.json()).then(res => {
                if(res.status === 'success') {
                    if(res.cart) { 
                        try {
                            App.State.cart = JSON.parse(res.cart); 
                            if(App.Cart && App.Cart.save) App.Cart.save(false);
                        } catch(e) { console.error("Cart Parse Error", e); }
                    }

                    if(res.wishlist) {
                        if(App.State.catalog && App.State.catalog.length > 0) {
                            const rawIds = String(res.wishlist).split(',').map(s => s.trim().replace('p-','')).filter(s => s !== "");
                            App.State.wishlist = App.State.catalog.filter(p => {
                                const cleanPId = String(p.id).replace('p-','');
                                return rawIds.some(rid => String(rid) === cleanPId);
                            });
                            localStorage.setItem('se_wish', JSON.stringify(App.State.wishlist));
                            if(document.getElementById('nav-wish-count')) document.getElementById('nav-wish-count').innerText = App.State.wishlist.length;
                            App.Catalog.renderBatch(true);
                        }
                    }

                    if(res.joinDate) {
                        const date = new Date(res.joinDate);
                        const el = document.getElementById('user-join-date');
                        if(el) el.innerText = date.toLocaleDateString();
                    }

                    if(res.currency) {
                        const gracePeriodActive = (Date.now() - App.State.lastCurrencyChange) < 15000;
                        if(!gracePeriodActive) {
                            App.State.currency = res.currency;
                            localStorage.setItem('se_curr', res.currency);
                            if(document.getElementById('curr-btn')) document.getElementById('curr-btn').innerText = res.currency;
                            App.Cart.render(); 
                        }
                    }

                    if(res.orders) {
                        App.State.history = res.orders;
                        App.Profile.renderOrders();
                    }
                }
            });
        }
    },

    Profile: {
        renderOrders: () => {
            const list = document.getElementById('order-history-list');
            if(!list) return;
            list.innerHTML = '';
            if(App.State.history.length === 0) {
                list.innerHTML = '<p class="text-muted text-center py-3">No orders yet.</p>';
                return;
            }
            App.State.history.forEach(o => {
                const date = new Date(o.date).toLocaleDateString();
                const displayTotal = o.total; 
                let itemsPreview = 'Unknown Items';
                try {
                   const parsed = JSON.parse(o.items);
                   if(Array.isArray(parsed)) itemsPreview = parsed.join(', ').substring(0, 50) + '...';
                } catch(e) { itemsPreview = o.items; }

                list.innerHTML += `
                <div class="card border-0 shadow-sm mb-3">
                    <div class="card-body">
                        <div class="d-flex justify-content-between align-items-center mb-2">
                            <span class="badge bg-primary">${o.id}</span>
                            <small class="text-muted">${date}</small>
                        </div>
                        <div class="d-flex justify-content-between align-items-center">
                            <div>
                                <h6 class="fw-bold m-0">${displayTotal}</h6>
                                <small class="text-muted" style="font-size:0.8rem">${itemsPreview}</small>
                            </div>
                            <span class="badge bg-light text-dark border">${o.status}</span>
                        </div>
                    </div>
                </div>`;
            });
        }
    },

    i18n: {
        toggleLang: () => {
            const map = { 'EN': 'FR', 'FR': 'AR', 'AR': 'EN' };
            App.State.lang = map[App.State.lang];
            localStorage.setItem('se_lang', App.State.lang);
            App.i18n.apply();
            App.Catalog.renderFilters(); App.Catalog.renderBatch(true); App.Cart.render();
            if(window.location.hash === '#wishlist') App.Wishlist.render();
            App.Router(false);
        },
        toggleCurrency: () => {
            App.State.lastCurrencyChange = Date.now(); 
            App.State.lastActive = Date.now();

            const map = { 'MAD': 'EUR', 'EUR': 'USD', 'USD': 'MAD' };
            App.State.currency = map[App.State.currency];
            localStorage.setItem('se_curr', App.State.currency);
            document.getElementById('curr-btn').innerText = App.State.currency;

            if(App.State.user) {
                fetch(API_URL, { 
                    method: 'POST', 
                    body: JSON.stringify({ action: 'updatePreference', data: { userId: App.State.user.id, currency: App.State.currency } }) 
                });
                const payload = { 
                    userId: App.State.user.id, 
                    cartJson: JSON.stringify(App.State.cart),
                    currency: App.State.currency 
                };
                fetch(API_URL, { method: 'POST', body: JSON.stringify({ action: 'syncCart', data: payload }) });
            }

            App.Catalog.renderBatch(true); App.Cart.render();
            if(window.location.hash === '#wishlist') App.Wishlist.render();
            if(window.location.hash === '#profile') App.Profile.renderOrders(); 
        },
        apply: () => {
            const lang = App.State.lang;
            const flagMap = { 'EN': '🇺🇸', 'FR': '🇫🇷', 'AR': '🇲🇦' };
            document.getElementById('lang-btn').innerText = flagMap[lang];
            if(lang === 'AR') document.documentElement.setAttribute('dir', 'rtl'); else document.documentElement.removeAttribute('dir');
            document.querySelectorAll('[data-i18n]').forEach(el => {
                const key = el.getAttribute('data-i18n');
                if(App.Strings[lang][key]) el.innerText = App.Strings[lang][key];
            });
        }
    },

    Utils: {
        getPriceObj: (item) => {
            const c = App.State.currency;
            if(c === 'EUR') return { current: item.price_EUR || 0, old: item.oldPrice_EUR || 0 };
            if(c === 'USD') return { current: item.price_USD || 0, old: item.oldPrice_USD || 0 };
            return { current: item.price_MAD || 0, old: item.oldPrice_MAD || 0 };
        },
        formatPrice: (amount) => {
            const s = App.Symbols[App.State.currency];
            if(App.State.currency === 'USD') return '$ ' + amount.toFixed(2);
            return amount.toFixed(2) + s;
        },
        checkStock: (item, req=1) => {
            if(!item) return { label: '?', class: 'bg-dark', disabled: true };
            if(item.stock === 0) return { label: App.t('soldOut'), class: 'bg-stock-out text-white', disabled: true };
            if(req > item.stock) return { label: App.t('lowStock'), class: 'bg-stock-low text-dark', disabled: false };
            return { label: App.t('inStock'), class: 'bg-stock-ok text-white', disabled: false };
        },
        getStockBadge: (s) => {
            if(s === 0) return { class: 'bg-stock-out', text: App.t('outOfStock') };
            if(s < 5) return { class: 'bg-stock-low', text: App.t('lowStock') };
            return { class: 'bg-stock-ok', text: App.t('inStock') };
        },
        loadStorage: (key) => { try { return JSON.parse(localStorage.getItem(key)) || []; } catch(e){ return []; } }
    },

    UI: {
        toast: (msg, type='success') => {
            const c = document.getElementById('toast-container');
            const t = document.createElement('div');
            t.className = `toast p-3 d-flex gap-3 border-${type}`;
            t.innerHTML = `<b>${msg}</b>`;
            c.appendChild(t); setTimeout(()=>t.remove(), 3000);
        },
        confirm: (t, m, fn) => {
            document.getElementById('conf-title').innerText=t; document.getElementById('conf-msg').innerText=m;
            const b = document.getElementById('conf-yes'); const nb = b.cloneNode(true); b.parentNode.replaceChild(nb, b);
            nb.addEventListener('click', ()=>{ fn(); bootstrap.Modal.getInstance(document.getElementById('confirmModal')).hide(); });
            new bootstrap.Modal(document.getElementById('confirmModal')).show();
        },
        flip: (img, target) => { /* Visual Effect Code */ }
    },

    Catalog: {
        init: (data) => {
            App.State.catalog = data;
            App.Catalog.renderFilters(); App.Catalog.initObserver(); App.Catalog.renderBatch(); App.i18n.apply();
        },
        renderFilters: () => {
            const c = document.getElementById('category-filters'); if(!c) return;
            const cats = ['All', ...new Set(App.State.catalog.map(i=>i.cat))];
            c.innerHTML = cats.map(k => `<button class="filter-chip ${k==='All'?'active':''}" onclick="App.Catalog.filter('${k}', this)">${k}</button>`).join('');
        },
        filter: (cat, btn) => {
            App.State.activeCat = cat; App.State.visibleCount = 0; document.getElementById('product-grid-root').innerHTML = '';
            if(btn) { document.querySelectorAll('.filter-chip').forEach(e=>e.classList.remove('active')); btn.classList.add('active'); }
            App.Catalog.renderBatch();
        },
        renderBatch: (reset) => {
            if(reset) { document.getElementById('product-grid-root').innerHTML=''; App.State.visibleCount=0; }
            const filtered = App.State.activeCat==='All' ? App.State.catalog : App.State.catalog.filter(i=>i.cat===App.State.activeCat);
            const batch = filtered.slice(App.State.visibleCount, App.State.visibleCount+App.State.batchSize);
            batch.forEach(i => document.getElementById('product-grid-root').appendChild(App.Catalog.createCard(i)));
            App.State.visibleCount += App.State.batchSize;
            document.getElementById('scroll-sentinel').style.display = (App.State.visibleCount >= filtered.length) ? 'none' : 'flex';
        },
        createCard: (item) => {
            const d = document.createElement('div'); d.className='col-lg-4 col-md-6 col-6';

            let badges = '';
            if(item.stock === 0) badges += `<div class="badge-float badge-out">${App.t('soldOut')}</div>`;
            else if(item.stock < 5) badges += `<div class="badge-float badge-low">${App.t('lowStock')}</div>`;
            else if(item.hot) badges += `<div class="badge-float badge-hot">HOT</div>`;

            const isWish = App.State.wishlist.some(w => w.id === item.id);
            const heartClass = isWish ? 'active' : '';
            const heartIcon = isWish ? 'bi-heart-fill text-danger' : 'bi-heart';

            const priceObj = App.Utils.getPriceObj(item);

            if(priceObj.old > 0) badges += `<div class="badge-float badge-sale">SALE</div>`;

            const pr = priceObj.old > 0 ? `<span class="text-decoration-line-through text-muted small">${App.Utils.formatPrice(priceObj.old)}</span> <span class="text-danger fw-bold">${App.Utils.formatPrice(priceObj.current)}</span>` : `<span class="text-primary fw-bold">${App.Utils.formatPrice(priceObj.current)}</span>`;
            const st = App.Utils.checkStock(item);

            d.innerHTML = `
            <div class="product-card">
                ${badges}
                <div class="product-img-wrapper">
                    <button class="wish-btn-card ${heartClass}" onclick="App.Wishlist.toggle('${item.id}', this); event.stopPropagation();"><i class="bi ${heartIcon}"></i></button>
                    <img src="${item.img}" class="product-img" loading="lazy" onclick="App.QuickView.open('${item.id}')"/>
                    <div class="desktop-actions">
                        <button class="btn btn-light rounded-pill shadow-sm fw-bold px-4" onclick="App.QuickView.open('${item.id}')">
                            <i class="bi bi-eye"></i> ${App.t('qvSize')}
                        </button>
                    </div>
                </div>
                <div class="p-3"><h6 class="product-title">${item.title}</h6><div class="d-flex justify-content-between align-items-center">${pr}<button class="btn btn-sm btn-dark rounded-circle" onclick="App.Cart.add('${item.id}', this)" ${st.disabled?'disabled':''}><i class="bi bi-plus"></i></button></div></div>
            </div>`;
            return d;
        },
        initObserver: () => { new IntersectionObserver(e=>{ if(e[0].isIntersecting) App.Catalog.renderBatch(); }).observe(document.getElementById('scroll-sentinel')); }
    },

    Cart: {
        add: (id, btn) => {
            App.State.lastActive = Date.now();
            const item = App.State.catalog.find(i=>i.id===id); if(!item) return;
            const ex = App.State.cart.find(c=>c.id===id && c.variant.name==='Regular');
            if(ex) ex.qty++; else App.State.cart.push({...item, qty:1, variant:{name:'Regular', mult:1.0}});
            App.Cart.save(); App.UI.toast(App.t('addedToCart'));
            if(btn) App.UI.flip(btn.closest('.product-card').querySelector('img'), 'nav-cart-target');
        },
        remove: (idx) => { 
            App.State.lastActive = Date.now();
            App.State.cart.splice(idx,1); App.Cart.save(); 
        },
        updateQty: (idx, d) => { 
            App.State.lastActive = Date.now();
            const i = App.State.cart[idx]; if(i.qty+d > 0) { i.qty+=d; App.Cart.save(); } 
        },
        checkClear: () => { if(App.State.cart.length===0) App.UI.toast(App.t('msgAlreadyEmpty')); else App.UI.confirm(App.t('empty'), App.t('areYouSure'), App.Cart.clear); },
        clear: () => { App.State.lastActive = Date.now(); App.State.cart=[]; App.Cart.save(); },
        save: (sync=true) => {
            localStorage.setItem('se_cart', JSON.stringify(App.State.cart));
            App.Cart.render(); App.Cart.updateBadge();
            if(sync) App.API.syncUp();
        },

        applyCoupon: () => {
            const code = document.getElementById('coupon-code').value.toUpperCase();
            const feedback = document.getElementById('coupon-feedback');
            if (code === 'SUSHI10') {
                feedback.innerText = 'Applied! 10% Off';
                feedback.className = 'small mb-3 text-success fw-bold';
            } else {
                feedback.innerText = 'Invalid Code';
                feedback.className = 'small mb-3 text-danger';
            }
            App.Cart.render();
        },

        setTip: (amount) => { App.State.tip = parseInt(amount); App.Cart.render(); },
        changeVariant: (idx, el) => {
            const val = el.value.split('|');
            App.State.cart[idx].variant = { name: val[0], mult: parseFloat(val[1]) };
            App.Cart.save();
        },
        duplicate: (idx) => {
            const item = {...App.State.cart[idx]};
            App.State.cart.splice(idx + 1, 0, item);
            App.Cart.save(); App.UI.toast('Duplicated');
        },

        updateBadge: () => { document.getElementById('nav-cart-count').innerText = App.State.cart.reduce((a,b)=>a+b.qty,0); },
        render: () => {
            const list = document.getElementById('cart-items-list');
            const empty = document.getElementById('cart-empty-view');
            const content = document.getElementById('cart-content-row');
            const float = document.getElementById('floating-cart');

            if(window.location.hash==='#cart') float.classList.remove('active');
            else if(App.State.cart.length>0) float.classList.add('active'); else float.classList.remove('active');

            if(App.State.cart.length===0) { if(empty) empty.classList.remove('d-none'); if(content) content.classList.add('d-none'); return; }
            if(empty) empty.classList.add('d-none'); if(content) content.classList.remove('d-none'); if(list) list.innerHTML='';

            let total = 0;
            App.State.cart.forEach((i, idx) => {
                const priceVal = App.Utils.getPriceObj(i).current; 
                const row = priceVal * i.variant.mult * i.qty; 
                total += row;
                list.innerHTML += `<div class="d-flex gap-3 mb-3 border-bottom pb-3"><img src="${i.img}" width="60" class="rounded"/><div class="flex-grow-1"><div class="d-flex justify-content-between"><h6>${i.title}</h6><b>${App.Utils.formatPrice(row)}</b></div><div class="d-flex align-items-center gap-2 mb-2"><span class="stock-dot ${App.Utils.getStockBadge(20).class}"></span><small class="text-muted" style="font-size:0.75rem">${App.t('inStock')}</small></div><div class="d-flex justify-content-between align-items-end"><select class="variant-select" onchange="App.Cart.changeVariant(${idx}, this)"><option value="Regular|1.0" ${i.variant.name==='Regular'?'selected':''}>Regular</option><option value="Box|1.2" ${i.variant.name==='Box'?'selected':''}>Box (1.2x)</option><option value="Party|1.5" ${i.variant.name==='Party'?'selected':''}>Party (1.5x)</option></select><div class="d-flex align-items-center gap-2"><button class="btn btn-sm btn-outline-secondary py-0" onclick="App.Cart.updateQty(${idx},-1)">-</button><b>${i.qty}</b><button class="btn btn-sm btn-outline-secondary py-0" onclick="App.Cart.updateQty(${idx},1)">+</button><button class="btn btn-sm text-muted border-0" onclick="App.Cart.duplicate(${idx})"><i class="bi bi-files"></i></button><button class="btn btn-sm text-danger border-0" onclick="App.Cart.remove(${idx})"><i class="bi bi-trash"></i></button></div></div></div></div>`;
            });

            let couponDisc = 0;
            const feedback = document.getElementById('coupon-feedback');
            if(feedback && feedback.innerText.includes('Applied')) {
                couponDisc = total * 0.10;
                document.getElementById('row-disc').classList.remove('d-none');
            } else {
                document.getElementById('row-disc').classList.add('d-none');
            }

            const finalTotal = total + App.State.tip - couponDisc; 
            App.State.currentTotal = finalTotal;

            document.getElementById('sum-sub').innerText = App.Utils.formatPrice(total);
            document.getElementById('sum-disc').innerText = '-' + App.Utils.formatPrice(couponDisc);
            document.getElementById('sum-total').innerText = App.Utils.formatPrice(finalTotal);
            document.getElementById('float-total').innerText = App.Utils.formatPrice(finalTotal);
            document.getElementById('float-count').innerText = App.State.cart.reduce((a,b)=>a+b.qty,0);
        },
        checkout: () => {
            const name = document.getElementById('checkout-name').value;
            const phone = document.getElementById('checkout-phone').value;
            const address = document.getElementById('checkout-address').value;
            const method = document.getElementById('checkout-method').value;
            const time = document.getElementById('order-time').value || 'ASAP';
            const note = document.getElementById('order-note').value;

            if(!name || !phone) return App.UI.toast(App.t('yourName') + ' Required', 'danger');
            if(App.State.orderType === 'delivery' && !address) return App.UI.toast(App.t('delAddr') + ' Required', 'danger');

            const btn = document.getElementById('checkout-btn');
            btn.innerHTML = '<span class="spinner-border spinner-border-sm"></span> Processing...';
            btn.disabled = true;

            const orderData = {
                userId: App.State.user ? App.State.user.id : null,
                name: name,
                phone: phone,
                address: App.State.orderType === 'delivery' ? address : 'Pickup',
                total: App.State.currentTotal || 0, // RAW NUMBER
                currency: App.State.currency, // CURRENCY CODE
                method: method,
                items: JSON.stringify(App.State.cart.map(i => `${i.qty}x ${i.title} (${i.variant.name})`))
            };

            fetch(API_URL, { method: 'POST', body: JSON.stringify({ action: 'placeOrder', data: orderData }) })
            .then(r => r.json())
            .then(res => {
                if(res.status === 'success') {
                    const orderId = res.orderId;
                    let msg = `*NEW ORDER ${orderId}* %0A`;
                    msg += `👤 ${name} (${phone}) %0A`;
                    msg += `🚚 ${App.State.orderType.toUpperCase()} ${orderData.address} %0A`;
                    msg += `⏰ ${time} %0A`;
                    if(note) msg += `📝 ${note} %0A`;
                    msg += `--------------------%0A`;
                    App.State.cart.forEach(i => msg += `🍱 ${i.qty}x ${i.title} [${i.variant.name}] %0A`);
                    msg += `--------------------%0A`;
                    msg += `💰 *TOTAL: ${App.Utils.formatPrice(orderData.total)}*`;

                    App.State.history.unshift({
                        id: orderId, 
                        date: new Date().toLocaleDateString(), 
                        total: orderData.total, 
                        items: App.State.cart.length, 
                        status: 'Sent'
                    });
                    localStorage.setItem('se_hist', JSON.stringify(App.State.history));

                    App.State.cart = [];
                    App.Cart.save();

                    window.open(`https://wa.me/${App.Config.waNumber}?text=${msg}`, '_blank');
                    window.location.reload();
                } else {
                    App.UI.toast('Order Failed: ' + res.message, 'danger');
                    btn.disabled = false;
                    btn.innerHTML = 'TRY AGAIN';
                }
            })
            .catch(err => {
                App.UI.toast('Network Error', 'danger');
                btn.disabled = false;
                btn.innerHTML = 'TRY AGAIN';
            });
        }
    },

    QuickView: {
        open: (id) => {
            const i = App.State.catalog.find(x=>x.id===id); if(!i) return;
            App.State.qvItem = i; App.State.qvMult = 1.0; App.State.qvQty = 1;
            const priceVal = App.Utils.getPriceObj(i).current;
            document.getElementById('quickview-content').innerHTML = `<div class="p-4 text-center"><img src="${i.img}" class="img-fluid rounded mb-3"/><h3>${i.title}</h3><h2 class="text-primary">${App.Utils.formatPrice(priceVal)}</h2><button class="btn btn-primary w-100 mt-3" onclick="App.QuickView.add()">ADD</button></div>`;
            new bootstrap.Modal(document.getElementById('quickViewModal')).show();
        },
        add: () => { App.Cart.add(App.State.qvItem.id); bootstrap.Modal.getInstance(document.getElementById('quickViewModal')).hide(); }
    },

    Wishlist: {
        checkClear: () => { if(App.State.wishlist.length===0) App.UI.toast(App.t('msgAlreadyEmpty')); else App.UI.confirm(App.t('empty'), App.t('areYouSure'), App.Wishlist.clear); },
        clear: () => { App.State.wishlist=[]; localStorage.setItem('se_wish','[]'); App.Wishlist.render(); document.getElementById('nav-wish-count').innerText=0; },
        toggle: (id, btn) => { 
            App.State.lastActive = Date.now();
            const idx = App.State.wishlist.findIndex(w => w.id === id);
            if(idx > -1) {
                App.State.wishlist.splice(idx, 1);
                if(btn) { btn.classList.remove('active'); btn.innerHTML = '<i class="bi bi-heart"></i>'; }
                App.UI.toast('Removed from Favorites');
            } else {
                const item = App.State.catalog.find(i => i.id === id);
                if(item) {
                    App.State.wishlist.push(item);
                    if(btn) { btn.classList.add('active'); btn.innerHTML = '<i class="bi bi-heart-fill text-danger"></i>'; }
                    App.UI.toast('Added to Favorites');
                }
            }
            localStorage.setItem('se_wish', JSON.stringify(App.State.wishlist));
            document.getElementById('nav-wish-count').innerText = App.State.wishlist.length;
            if(window.location.hash === '#wishlist') App.Wishlist.render();

            if(App.State.user) {
                const wishPayload = { userId: App.State.user.id, items: App.State.wishlist.map(i=>i.id).join(',') };
                fetch(API_URL, { method: 'POST', body: JSON.stringify({ action: 'syncWishlist', data: wishPayload }) });
            }
        },
        render: () => { 
            const r = document.getElementById('wishlist-grid-root'); 
            if(!r) return;
            r.innerHTML=''; 
            if(App.State.wishlist.length === 0) {
                const l = App.State.lang || 'EN';
                r.innerHTML = `<div class="col-12 text-center py-5"><i class="bi bi-heart text-muted" style="font-size: 4rem;"></i><h4 class="mt-3 text-muted fw-bold">${App.Strings[l].wishlistEmptyTitle}</h4><p class="text-muted mb-4">${App.Strings[l].wishlistEmptySub}</p><button class="btn btn-primary rounded-pill px-5 py-2 fw-bold" onclick="window.location.hash='#catalog'">${App.Strings[l].goToMenu}</button></div>`;
                return;
            }
            // 🔥 FIXED DIV STRUCTURE
            App.State.wishlist.forEach(i => r.appendChild(App.Catalog.createCard(i))); 
        }
    },

    Router: (scroll=true) => {
        const h = window.location.hash || '#home';
        document.querySelectorAll('.module-section').forEach(e=>e.classList.remove('active'));
        const t = document.querySelector(h+'-module'); if(t) t.classList.add('active');
        document.getElementById('breadcrumbs').innerHTML = `<a href="#home">${App.t('home')}</a> <span class="breadcrumb-sep">></span> <span class="breadcrumb-item active">${App.t(h.replace('#',''))}</span>`;
        if(h==='#cart') document.getElementById('floating-cart').classList.remove('active');
        else App.Cart.render();
        if(h==='#profile') App.Auth.check();
        if(h==='#wishlist') App.Wishlist.render(); // Ensure render is called on route change
        if(scroll) window.scrollTo(0,0);
    }
};

document.addEventListener('DOMContentLoaded', () => {
    App.State.cart = App.Utils.loadStorage('se_cart');
    App.State.wishlist = App.Utils.loadStorage('se_wish');
    App.State.user = JSON.parse(localStorage.getItem('se_user'));
    App.State.lang = localStorage.getItem('se_lang') || 'EN';
    App.State.currency = localStorage.getItem('se_curr') || 'MAD';

    document.getElementById('curr-btn').innerText = App.State.currency;
    App.Auth.check();
    App.API.init(); 

    AOS.init();

    App.Cart.render(); 
    App.Cart.updateBadge();
    App.i18n.apply();

    App.Router(); window.addEventListener('hashchange', App.Router);

    if(App.State.user) {
        App.API.syncDown(App.State.user.id);
        setInterval(() => {
           const isIdle = (Date.now() - App.State.lastActive) > 15000;
           if(App.State.user && isIdle) App.API.syncDown(App.State.user.id);
        }, 10000);
    }
});
//
